package com.loyu3c.rental;
import org.json.*;import java.time.*;import org.junit.Test;import static org.junit.Assert.*;
public class SharedReportsTest {
    private JSONObject b()throws Exception{JSONObject b=new JSONObject();for(String key:new String[]{"owners","properties","units","leases","invoices","receipts","expenses","transfers","accounts","deposits","settlements"})b.put(key,new JSONArray());for(int i=1;i<=2;i++){String n=""+i;b.getJSONArray("owners").put(new JSONObject().put("id","o"+n).put("name","房東"+n).put("email","owner"+n+"@gmail.com"));b.getJSONArray("properties").put(new JSONObject().put("id","p"+n).put("name","BUILDING_"+n).put("ownerId","o"+n));b.getJSONArray("units").put(new JSONObject().put("id","u"+n).put("propertyId","p"+n).put("code","10"+n).put("type","房間"));b.getJSONArray("leases").put(new JSONObject().put("id","l"+n).put("unitId","u"+n).put("tenant","SECRET_TENANT_"+n).put("email","secret"+n+"@gmail.com").put("phone","PRIVATE_PHONE").put("note","PRIVATE_NOTE").put("unitCodeSnapshot","10"+n).put("start","2026-01-01").put("end","2026-12-31").put("rent",10000*i).put("deposit",20000*i).put("cycle","月繳"));b.getJSONArray("invoices").put(new JSONObject().put("id","i"+n).put("leaseId","l"+n).put("month","2026-10").put("kind","租金").put("due","2026-10-05").put("rent",10000*i).put("water",0).put("electricity",0));b.getJSONArray("accounts").put(Bookkeeping.account("ACCOUNT_"+n,"銀行","2026-01-01",100,"p"+n).put("id","a"+n).put("ownerId","o"+n));}return b;}
    @Test public void ownerReportNeverContainsTenantPersonalDataOrOtherOwnerProperty()throws Exception{JSONObject r=SharedReports.owner(b(),YearMonth.of(2026,10),"o1");String s=r.toString();for(String secret:new String[]{"SECRET_TENANT_","secret1@gmail.com","PRIVATE_PHONE","PRIVATE_NOTE","BUILDING_2","ACCOUNT_2"})assertFalse(s.contains(secret));assertEquals(10000,r.getJSONObject("total").getLong("billed"));assertEquals(1,r.getJSONArray("properties").length());assertEquals(1,r.getJSONArray("properties").getJSONObject(0).getInt("rented"));assertEquals(1,r.getJSONArray("units").length());assertEquals(1,r.getJSONArray("accounts").length());}
    @Test public void tenantReportOnlyContainsOwnBillsDepositsAndPayments()throws Exception{JSONObject b=b();JSONArray bills=b.getJSONArray("invoices"),payments=b.getJSONArray("receipts");payments.put(Ledger.receipt("l1","2026-10-05","SECRET_BANK",10000,"PRIVATE_NOTE",bills,payments));b.getJSONArray("deposits").put(Deposits.movement("l1","a1","2026-01-01","收到押金",20000,"PRIVATE_NOTE"));JSONObject r=SharedReports.tenant(b,"l1");String s=r.toString();for(String secret:new String[]{"SECRET_TENANT_2","secret2@gmail.com","PRIVATE_PHONE","PRIVATE_NOTE","SECRET_BANK","BUILDING_2"})assertFalse(s.contains(secret));assertEquals(1,r.getJSONArray("bills").length());assertEquals(10000,r.getJSONArray("bills").getJSONObject(0).getLong("paid"));assertEquals(20000,r.getJSONObject("depositSummary").getLong("held"));assertEquals(1,r.getJSONArray("payments").length());}
    @Test public void unassignedPropertyIsNotPublishedAndMixedAccountIsWithheld()throws Exception{JSONObject b=b();b.getJSONArray("properties").getJSONObject(1).remove("ownerId");assertEquals(0,SharedReports.owner(b,YearMonth.of(2026,10),"o2").getJSONArray("properties").length());b.getJSONArray("receipts").put(new JSONObject().put("id","r").put("leaseId","l2").put("date","2026-10-01").put("amount",50).put("accountId","a1").put("allocations",new JSONArray()));JSONObject r=SharedReports.owner(b,YearMonth.of(2026,10),"o1");assertTrue(r.getJSONArray("accounts").getJSONObject(0).getBoolean("withheld"));assertEquals(0,r.getJSONArray("accounts").getJSONObject(0).getLong("balance"));}
    @Test public void unknownOwnerAndCrossOwnerPaymentAreRejected()throws Exception{JSONObject b=b();try{SharedReports.owner(b,YearMonth.of(2026,10),"missing");fail();}catch(IllegalArgumentException expected){}try{Owners.paymentAccount(b,"p1","a2");fail();}catch(IllegalArgumentException expected){}Owners.paymentAccount(b,"p1","a1");}
}
